def similar(a, b): return sum(1 for x, y in zip(a, b) if x == y) / max(len(a), len(b))
pairs = [("Jon Smith", "John Smith"), ("Jon Smith", "Zebra X")]
for a, b in pairs: print(a, "vs", b, "-> %.2f" % similar(a, b))
